class Controller:
    def __init__(self):
        self.generation = 0
        self.rows = []
        self.decisions = {}
        self.busy = False
        self._latest_generation = 0
        self._polled_completed = False
        self._finished = False

    def start(self):
        self.generation += 1
        self._latest_generation = self.generation
        self.busy = True
        self._polled_completed = False
        self._finished = False
        return self.generation

    def poll_status(self, generation, status):
        if generation != self._latest_generation:
            return False

        if status == "completed":
            if self._polled_completed:
                return False
            self._polled_completed = True
            return True
        elif status in ("queued", "running"):
            return False
        elif status == "failed":
            self.busy = False
            return False
        else:
            return False

    def finish(self, generation, rows):
        if generation != self._latest_generation or self._finished:
            return False

        self.rows = list(rows)
        self.busy = False
        self._finished = True
        return True

    def set_decision(self, job_id, value):
        self.decisions[job_id] = value

